package com.ruoyi.framework.audit;
import org.springframework.context.annotation.Configuration;import org.springframework.transaction.annotation.EnableTransactionManagement;import org.springframework.web.servlet.config.annotation.*;import org.springframework.web.servlet.HandlerInterceptor;import org.springframework.web.method.HandlerMethod;import jakarta.servlet.http.*;import com.ruoyi.common.annotation.Log;
@Configuration @EnableTransactionManagement(order=100) public class AuditConfig implements WebMvcConfigurer {
 private final AuditRecorder recorder;public AuditConfig(AuditRecorder recorder){this.recorder=recorder;}
 public void addInterceptors(InterceptorRegistry registry){registry.addInterceptor(new HandlerInterceptor(){public boolean preHandle(HttpServletRequest r,HttpServletResponse s,Object h){AuditContext c=AuditContext.CURRENT.get();if(c!=null){recorder.actor(c);if(r.getMethod().equals("GET")&&r.getRequestURI().matches("/system/(user|role)/[0-9]+")){c.title="人员权限详情查询";c.action="QUERY";c.before=recorder.snapshot(c,null,null);}if(h instanceof HandlerMethod m){Log a=m.getMethodAnnotation(Log.class);if(a!=null&&(!r.getMethod().equals("GET")||a.businessType().name().equals("EXPORT")||r.getRequestURI().startsWith("/monitor/")||r.getRequestURI().matches("/system/(user|role)/[0-9]+"))){c.title=a.title();c.action=a.businessType().name();}}}return true;}}).order(-100);}
}
